import * as React from 'react';
import Button from '@mui/material/Button';
import Dialog from '@mui/material/Dialog';
import DialogActions from '@mui/material/DialogActions';
import DialogContent from '@mui/material/DialogContent';
import DialogTitle from '@mui/material/DialogTitle';
import {
  Autocomplete,
  Box,
  Grid,
  Stack,
  TextField,
  Typography,
  useMediaQuery,
} from '@mui/material';
import LocalShippingOutlinedIcon from '@mui/icons-material/LocalShippingOutlined';
import FieldHeader from '../../../components/FieldHeader';
import { theme } from '../../../theme';
import { useFormik } from 'formik';
import { useEffect, useMemo, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { useAppDispatch } from '../../../store/hooks';
import { useSelector } from 'react-redux';
import {
  selectSupplierNameOrMobile,
  selectReceiptNo,
} from '../store/BasketSelector';
import { addMobileReceiptID } from '../store/BasketSlice';
import { HEADER_GRADIENT } from '../../../theme/appColors';
import { useGetSupplierByMobileQuery } from '../../posApi';
import { useNotifier } from '../../../core/Notifier';
import { IInventoryBasketStates } from '../../../core/Interface/property.interface';
import { ICustomerMobileDatails } from '../../../core/Interface/customer.interface';

interface IMobile {
  openModel?: boolean;
  title: string;
  handleCloseDialog: (close: boolean) => void;
}

const AddSupplierDetails = ({
  title,
  openModel = false,
  handleCloseDialog,
}: IMobile) => {
  const { t } = useTranslation(['purchase']);
  const [open] = React.useState(openModel);
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const dispatch = useAppDispatch();
  const selectMobile = useSelector(selectSupplierNameOrMobile);
  const selectReceiptId = useSelector(selectReceiptNo);
  const [supplierNumber, setSupplierNumber] = useState<string>('');
  const [mobileOptions, setMobileOptions] = useState<string[]>([]);
  const { showErrorMessage } = useNotifier();

  const {
    data: supplierData,
    isFetching,
  } = useGetSupplierByMobileQuery(supplierNumber, {
    skip: !supplierNumber,
  });

  useEffect(() => {
    if (supplierData) {
      const suppliers = (
        supplierData.data as { suppliers: ICustomerMobileDatails[] }
      )?.suppliers;
      if (suppliers) {
        setMobileOptions(
          suppliers.map((customer: ICustomerMobileDatails) => customer.mobile)
        );
      }
    }
  }, [supplierData]);

  useEffect(() => {
    if (selectMobile) {
      setSupplierNumber(selectMobile);
    }
  }, [selectMobile]);

  const handleMobileNumberChange = (
    event: React.ChangeEvent<HTMLInputElement>
  ) => {
    const { value } = event.target;
    setSupplierNumber(value);
    formik.setFieldValue('supplierNameOrMobile', value);
  };

  const handleOptionSelect = (value: string | null) => {
    if (value) {
      setSupplierNumber(value);
      formik.setFieldValue('supplierNameOrMobile', value);
    }
  };

  const handleClose = () => {
    handleCloseDialog(false);
  };

  const formik = useFormik({
    initialValues: {
      supplierNameOrMobile: selectMobile || '',
      receiptNo: selectReceiptId,
    },
    enableReinitialize: true,
    onSubmit: async (values) => {
      try {
        const selectSupplier: IInventoryBasketStates = values;
        dispatch(addMobileReceiptID(selectSupplier));
        handleClose();
      } catch (error) {
        showErrorMessage('Something went wrong');
      }
    },
  });

  const formValid = useMemo(() => {
    const isMobileNoValid =
      formik.values.supplierNameOrMobile !== undefined &&
      formik.values.supplierNameOrMobile !== null &&
      formik.values.supplierNameOrMobile.trim() !== '';
    const isReceiptIdValid =
      formik.values.receiptNo !== undefined &&
      formik.values.receiptNo  !== null &&
      formik.values.receiptNo.trim() !== '';

    return isMobileNoValid && isReceiptIdValid;
  }, [formik]);

  return (
    <div>
      <form onSubmit={formik.handleSubmit}>
        <Dialog
          aria-describedby="alert-dialog-description"
          classes={{ paper: 'inherit' }}
          fullScreen={isMobile}
          fullWidth={isMobile}
          maxWidth="lg"
          open={open}
          PaperProps={{ sx: { borderRadius: isMobile ? 0 : '12px', overflow: 'hidden' } }}
        >
          <DialogTitle sx={{ p: 0 }}>
            <Box sx={{ background: HEADER_GRADIENT, px: 3, py: 2 }}>
              <Stack alignItems="center" direction="row" spacing={1.5}>
                <Box sx={{ alignItems: 'center', background: 'rgba(255,255,255,0.15)', borderRadius: '8px', display: 'flex', height: 36, justifyContent: 'center', width: 36, flexShrink: 0 }}>
                  <LocalShippingOutlinedIcon sx={{ color: '#fff', fontSize: 20 }} />
                </Box>
                <Box>
                  <Typography sx={{ color: '#fff', fontSize: '1rem', fontWeight: 800, lineHeight: 1.2 }}>{title}</Typography>
                  <Typography sx={{ color: 'rgba(255,255,255,0.7)', fontSize: '0.72rem', fontWeight: 500 }}>Select supplier</Typography>
                </Box>
              </Stack>
            </Box>
          </DialogTitle>
          <DialogContent sx={{ width: isMobile ? 'auto' : '40vw', px: 3, pt: 3, pb: 1 }}>
            <Box>
              <Grid container>
                <GridItem>
                  <FieldHeader
                    title={t('purchase:supplierNameorMobileNumber')}
                  />
                  <Autocomplete
                    freeSolo
                    getOptionLabel={(option) => option}
                    loading={isFetching}
                    noOptionsText="Can't find number"
                    onChange={(event, value) => handleOptionSelect(value)}
                    options={mobileOptions}
                    renderInput={(params) => (
                      <TextField
                        autoComplete="off"
                        {...params}
                        onChange={handleMobileNumberChange}
                        placeholder="Mobile Number"
                      />
                    )}
                    renderOption={(props, option) => (
                      <li {...props}>
                        <Grid
                          alignItems="center"
                          container
                          onClick={() => handleOptionSelect(option)}
                        >
                          <Grid
                            item
                            sx={{ display: 'flex', width: 44, height: 34 }}
                          >
                            {option}
                          </Grid>
                        </Grid>
                      </li>
                    )}
                    sx={{ width: '100%' }}
                    value={supplierNumber || ''}
                  />
                </GridItem>
                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('purchase:receiptNumber')} />
                  <TextField
                    autoComplete="off"
                    placeholder={t('purchase:receiptNumber')}
                    size="small"
                    {...formik.getFieldProps('receiptNo')}
                    InputProps={{ inputProps: { min: 1 } }}
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                  />
                </GridItem>
              </Grid>
            </Box>
          </DialogContent>
          <DialogActions sx={{ borderTop: '1px solid #E2E8F0', gap: 1.5, px: 3, py: 2 }}>
            <Button
              onClick={handleClose}
              sx={{ borderColor: '#CBD5E1', borderRadius: '8px', color: '#475569', fontWeight: 600, height: 40, minWidth: 110, px: 3, textTransform: 'none', '&:hover': { background: '#F1F5F9', borderColor: '#94A3B8' } }}
              variant="outlined"
            >
              {t('purchase:cancel')}
            </Button>
            <Button
              autoFocus
              disabled={!formValid}
              onClick={() => {
                formik.handleSubmit();
              }}
              sx={{ background: HEADER_GRADIENT, borderRadius: '8px', boxShadow: '0 4px 14px rgba(15,29,77,0.25)', color: '#fff', fontWeight: 700, height: 40, minWidth: 110, px: 3, textTransform: 'none', '&:hover': { opacity: 0.9 }, '&.Mui-disabled': { background: '#CBD5E1', color: '#94A3B8', boxShadow: 'none' } }}
              type="submit"
              variant="contained"
            >
              {t('purchase:add')}
            </Button>
          </DialogActions>
        </Dialog>
      </form>
    </div>
  );
};

export default React.memo(AddSupplierDetails);

// eslint-disable-next-line react/no-multi-comp
const GridItem = ({ ...rest }) => {
  return (
    <Grid
      item
      key={1}
      lg={12}
      sm={12}
      xs={12}
      {...rest}
    />
  );
};
