import { RootState } from '../../../store';
import { createSelector } from '@reduxjs/toolkit';
import { BasketState } from './BasketSlice';

export const selectBasket = (state: RootState): BasketState =>
  state.purchaseBasket;

export const selectBasketItems = createSelector(
  selectBasket,
  (basket) => basket.items
);

export const selectDiscount = createSelector(selectBasket, (basket) => ({
  discount: basket.discount,
  discountAsPercentage: basket.discountAsPercentage,
}));

export const selectSupplierNameOrMobile = createSelector(
  selectBasket,
  (basket) => basket.supplierNameOrMobile
);

export const selectReceiptNo = createSelector(
  selectBasket,
  (basket) => basket.receiptNo
);

export const selectTotal = createSelector(selectBasket, (basket) => {
  const subtotal = basket.items.reduce((acc, item) => acc + item.total, 0);
  const discountAmount = basket.discountAsPercentage
    ? (subtotal * (basket.discount ?? 0)) / 100
    : basket.discount ?? 0;
  return {
    subtotal,
    discount: discountAmount,
    total: subtotal - discountAmount,
    discountAsPercentage: basket.discountAsPercentage,
    discountPercentage: basket.discountAsPercentage ? basket.discount ?? 0 : 0,
  };
});
